private:
    int n;
    vector<int> tree;

public:
    Fenwick(int n) : n(n), tree(n + 1, 0) {}

    // 在下标 idx 位置加上 delta
    void add(int idx, int delta) {
        while (idx <= n) {
            tree[idx] += delta;
            idx += idx & -idx;
        }
    }

    // 查询前缀和 [1..idx]
    int sum(int idx) {
        int res = 0;
        while (idx > 0) {
            res += tree[idx];
            idx -= idx & -idx;
        }
        return res;
    }

    // 查询区间和 [l..r]
    int rangeSum(int l, int r) {
        return sum(r) - sum(l - 1);
    }
};

// 计算单组测试数据答案
long long solveCase(int n, const vector<int>& a) {
    // pos[x] 保存值 x 的所有出现位置
    vector<vector<int>> pos(n + 1);
    for (int i = 1; i <= n; i++) {
        pos[a[i]].push_back(i);
    }

    Fenwick bit(n);
    long long ans = 0;

    // 按值从小到大处理
    for (int x = 1; x <= n; x++) {
        vector<int>& arr = pos[x];

        // 先统计值 x 的所有相邻等值对贡献
        for (int i = 0; i + 1 < (int)arr.size(); i++) {
            int l = arr[i];
            int r = arr[i + 1];
            ans += bit.rangeSum(l, r);
        }

        // 再把值 x 的所有位置加入树状数组
        for (int p : arr) {
            bit.add(p, 1);
        }
    }

    return ans;
}

